head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.trigger01_onclick = function(e) {
    var winID = "sample01"
    var url = "./windowContainer_setWindowPosition_WPF-1726_(WSQ-2854_)_sub.xml";
    mdi.createWindow(winID, null, url, winID);
};
scwin.trigger4_onclick = function(e) {
    mdi.setWindowSize(200, '300');
    mdi.setWindowPosition(30, '10px');
};
scwin.trigger5_onclick = function(e) {
    mdi.setWindowSize('200', 300);
    mdi.setWindowPosition('300px', 10);
};
scwin.getStyle = function(style) {
    var el = scwin.__getDom($p.id + 'mdi_subWindow0');
    return el.style[style];
}
scwin.checktype = function() {
    return typeof mdi_subWindow0;
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
}
